<?php
require __DIR__.'/config.php'; require_login(); $title='Raadi Documents';
$q=trim((string)($_GET['q']??'')); $type=trim((string)($_GET['type']??''));
$sql='SELECT * FROM documents WHERE 1=1'; $args=[]; if(($_SESSION['role']??'staff')!=='admin'){ $sql.=' AND uploaded_by=?'; $args[]=(int)$_SESSION['user_id']; }
if($q!==''){ $sql.=' AND (mobile LIKE ? OR ref_no LIKE ? OR full_name LIKE ? OR identity_number LIKE ?)'; $like='%'.$q.'%'; array_push($args,$like,$like,$like,$like); }
if($type!=='' && in_array($type,categories(),true)){ $sql.=' AND document_type=?'; $args[]=$type; }
$sql.=' ORDER BY created_at DESC LIMIT 500'; $stmt=$pdo->prepare($sql); $stmt->execute($args); $rows=$stmt->fetchAll();
require __DIR__.'/header.php';
?>
<div class="section-heading"><div><h3>Raadi dukumentiga</h3><p>Ku raadi mobile, REF.No., magaca ama aqoonsiga qofka.</p></div><a class="btn primary" href="document_new.php">＋ Xaree document</a></div>
<?php if(isset($_GET['saved'])): ?><div class="success">Documentiga si guul leh ayaa loo xareeyey.</div><?php endif; ?><?php if(($_GET['deleted']??'')==='1'): ?><div class="success">Documentiga waa la tirtiray.</div><?php endif; ?>
<form class="search-bar" method="get"><span>⌕</span><input name="q" value="<?=e($q)?>" placeholder="Geli mobile number, REF.No., magac ama aqoonsi..."><select name="type"><option value="">Dhammaan noocyada</option><?php foreach(categories() as $c): ?><option value="<?=e($c)?>" <?=$type===$c?'selected':''?>><?=e($c)?></option><?php endforeach; ?></select><button class="btn primary">Raadi</button></form>
<div class="table-wrap"><table><thead><tr><th>REF.No.</th><th>Magaca qofka</th><th>Mobile</th><th>Aqoonsi No.</th><th>Nooca</th><th>Taariikh</th><th>Falalka</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="7" class="empty">Natiijo lama helin.</td></tr><?php endif; ?><?php foreach($rows as $r): ?><tr><td><strong><?=e($r['ref_no'])?></strong></td><td><?=e($r['full_name'])?><small class="table-sub"><?=e($r['address'])?></small></td><td><?=e($r['mobile'])?></td><td><?=e($r['identity_number'])?></td><td><span class="pill"><?=e($r['document_type'])?></span></td><td><?=e(date('d/m/Y',strtotime($r['created_at'])))?></td><td><div style="display:flex;gap:7px;align-items:center;flex-wrap:wrap"><a class="pdf-link" href="document_view.php?id=<?=(int)$r['id']?>">View</a><a class="pdf-link" href="document_edit.php?id=<?=(int)$r['id']?>">Update Document</a><a class="pdf-link" href="download.php?id=<?=(int)$r['id']?>">↓ Download</a><a class="pdf-link" target="_blank" href="print.php?id=<?=(int)$r['id']?>">Print</a><form method="post" action="delete.php" style="display:inline" onsubmit="return confirm('Ma hubtaa inaad tirtirayso documentigan? Tallaabadan lama celin karo.');"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button type="submit" class="btn secondary" style="padding:6px 8px;color:#b13e46">Delete</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><p class="muted small">Waxaa la muujiyey <?=count($rows)?> natiijo (ugu badnaan 500).</p>
